import type { ApplicationEnvironment } from "@kasperrt/smolter/preact";
import { configureApplication } from "@kasperrt/smolter/preact/client";

const environment: ApplicationEnvironment = {
  resolveURL(url) {
    if (url.origin === "https://legacy.example") {
      return new URL(url.pathname + url.search + url.hash, location.origin);
    }

    return url;
  },
};

configureApplication(environment);
